  builder_.add_CRS(CRS);
  builder_.add_CLASS_LEGEND(CLASS_LEGEND);
  builder_.add_UNIT(UNIT);
  builder_.add_QUANTITY_NAME(QUANTITY_NAME);
  builder_.add_TILESET_NAME(TILESET_NAME);
  builder_.add_TILESET_ID(TILESET_ID);
  builder_.add_PAYLOAD_FORMAT(PAYLOAD_FORMAT);
  builder_.add_TILING_SCHEME(TILING_SCHEME);
  builder_.add_PIXEL_REGISTRATION(PIXEL_REGISTRATION);
