  auto CLASS_LEGEND__ = CLASS_LEGEND ? _fbb.CreateVector<::flatbuffers::Offset<SRTClass>>(*CLASS_LEGEND) : 0;
  auto CRS__ = CRS ? _fbb.CreateString(CRS) : 0;
  auto AFFINE_TRANSFORM__ = AFFINE_TRANSFORM ? _fbb.CreateVector<double>(*AFFINE_TRANSFORM) : 0;
  auto HORIZONTAL_DATUM_NAME__ = HORIZONTAL_DATUM_NAME ? _fbb.CreateString(HORIZONTAL_DATUM_NAME) : 0;
  auto EPOCH__ = EPOCH ? _fbb.CreateString(EPOCH) : 0;
