inline const SRT *GetSRT(const void *buf) {
  return ::flatbuffers::GetRoot<SRT>(buf);
}

inline const SRT *GetSizePrefixedSRT(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SRT>(buf);
}

inline const char *SRTIdentifier() {
  return "$SRT";
}

inline bool SRTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SRTIdentifier());
}

inline bool SizePrefixedSRTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SRTIdentifier(), true);
}

template <bool B = false>
inline bool VerifySRTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SRT>(SRTIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSRTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SRT>(SRTIdentifier());
}

inline void FinishSRTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SRT> root) {
  fbb.Finish(root, SRTIdentifier());
}

inline void FinishSizePrefixedSRTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SRT> root) {
  fbb.FinishSizePrefixed(root, SRTIdentifier());
}

